"use client";
import { useEffect, useState } from "react";
import { CadViewer } from "@/components/cad-viewer";
const B1 = "";
const B2 = "";
export default function Page() {
  const [c, setC] = useState(B1);
  useEffect(() => {
    let i = 0;
    const id = setInterval(() => { setC(i % 2 ? B1 : B2); i++; }, 1200);
    return () => clearInterval(id);
  }, []);
  return <div style={{width:"100vw",height:"100vh"}}><CadViewer dxfContent={c} className="w-full h-full" /></div>;
}
